{
    "message": "def set_params(op_name, params):
    """Set multiple parameters on an operation in one call.
      params: {param_name: {"value": <v>, "unit": "mm"|"raw"|"bool"|"choice"}, ...}
    Use the param names and expressions returned by add_operation() or list_params()
    to build this dict. Wrong param name → error listing all available names.
    Returns {param_name: {value, unit}, ...} for every param that was set."""
    cam = get_cam()
    _, op = _find_op(cam, op_name)
    results = {}
    avail = None
    for param_name, spec in params.items():
        value = spec["value"]
        unit = spec.get("unit", "mm")
        p = op.parameters.itemByName(param_name)
        if p is None:
            if avail is None:
                avail = sorted(op.parameters.item(i).name
                               for i in range(op.parameters.count))
            raise RuntimeError(f"Parameter {param_name!r} not found on {op_name!r}. "
                               f"Available: {avail}")
        if unit == "mm":
            p.value.value = float(value) / MM
        elif unit == "bool":
            p.value.value = bool(value)
        elif unit == "choice":
            p.expression = "'" + str(value) + "'"
        else:
            p.value.value = float(value)
        results[param_name] = {"value": value, "unit": unit}
    adsk.doEvents()
    return {"op": op_name, "params_set": results}

